/* Shortcut Press — Photo Editing in GIMP guide content (generated by tools/site/build.mjs). */
window.SP_GUIDE = {"id":"gimp-photo-editing","slug":"gimp-photo-editing","title":"Photo Editing in GIMP","software":"GIMP","apps":["GIMP"],"intro":"Edit photos in GIMP, the free image editor: find your way around the workspace, crop and straighten, fix exposure and color with levels and curves, retouch with healing and cloning, cut out subjects with selections and masks, and add text and export for the web and print.","platformNote":"Shortcuts are shown for GIMP 3 on Windows and Linux. On a Mac, use Cmd in place of Ctrl.","files":[{"name":"lake-dull.png","title":"Dull landscape","desc":"A flat, slightly blue-tinted lake scene to fix with levels, curves and white balance.","size":"48 KB"},{"name":"lake-tilted.png","title":"Tilted horizon","desc":"The same scene with a crooked horizon, to straighten and crop.","size":"127 KB"},{"name":"old-scan.png","title":"Dusty scan","desc":"A scanned sunset illustration covered in light and dark dust specks and a long scratch, for healing and cloning.","size":"16 KB"},{"name":"mug-product.png","title":"Product shot","desc":"A red mug on a gray background, for selections, masks and a new background.","size":"10 KB"}],"shortcuts":[{"keys":"R","action":"Rectangle Select tool","app":"GIMP"},{"keys":"E","action":"Ellipse Select tool","app":"GIMP"},{"keys":"F","action":"Free Select (lasso) tool","app":"GIMP"},{"keys":"U","action":"Fuzzy Select (magic wand) tool","app":"GIMP"},{"keys":"Shift+C","action":"Crop tool","app":"GIMP"},{"keys":"Shift+M","action":"Measure tool","app":"GIMP"},{"keys":"H","action":"Heal tool","app":"GIMP"},{"keys":"C","action":"Clone tool","app":"GIMP"},{"keys":"T","action":"Text tool","app":"GIMP"},{"keys":"M","action":"Move tool","app":"GIMP"},{"keys":"[","action":"Make the brush smaller","app":"GIMP"},{"keys":"]","action":"Make the brush bigger","app":"GIMP"},{"keys":"1","action":"Zoom to 100%","app":"GIMP"},{"keys":"Ctrl+I","action":"Invert the selection","app":"GIMP"},{"keys":"Ctrl+Shift+N","action":"New layer","app":"GIMP"},{"keys":"Ctrl+Shift+D","action":"Duplicate the layer","app":"GIMP"},{"keys":"Ctrl+Shift+E","action":"Export As","app":"GIMP"},{"keys":"X","action":"Swap foreground and background colors","app":"GIMP"},{"keys":"D","action":"Reset colors to black and white","app":"GIMP"},{"keys":"Ctrl+Shift+A","action":"Select none","app":"GIMP","practice":false,"note":"Your browser uses this shortcut to search tabs."},{"keys":"Ctrl+Shift+J","action":"Fit the image in the window","app":"GIMP","practice":false,"note":"Your browser uses this shortcut for its developer tools."}],"lessons":[{"id":"workspace","title":"The GIMP workspace","summary":"Open an image, find the toolbox, tool options, layers and undo history, zoom and pan, and understand the difference between saving and exporting.","diagram":{"type":"tree","root":"GIMP window","items":[["Toolbox (left)",1],["Tool Options (under the toolbox)",2,true],["Canvas (middle)",1],["Layers, Channels, Paths (right)",1],["Undo History",2]],"caption":"Every tool's settings live in Tool Options"},"steps":[{"title":"Open an image","body":"<p>Choose <em>File › Open</em> and pick <strong>lake-dull.png</strong>. The toolbox is on the left; below it, <em>Tool Options</em> shows the settings for whichever tool is active. On the right, the <em>Layers</em> panel lists the image's layers. If a panel is missing, find it under <em>Windows › Dockable Dialogs</em>.</p>"},{"title":"Grouped tools","body":"<p>Tools are grouped: a small triangle on a tool's icon means there are more under it. Pressing a tool's key (<kbd>R</kbd> for Rectangle Select, <kbd>M</kbd> for Move) is usually quicker. Hover any tool to see its name and shortcut.</p>"},{"title":"Zoom and pan","body":"<p><kbd>1</kbd> shows the image at 100% (one image pixel per screen pixel), ideal for judging detail; <kbd>Ctrl</kbd> <kbd>Shift</kbd> <kbd>J</kbd> fits the whole image in the window. Ctrl+scroll zooms, and holding the Space bar while dragging pans.</p>"},{"title":"Save versus export","body":"<p><em>File › Save</em> writes an <code>.xcf</code> file: GIMP's own format, keeping layers, masks and selections so you can keep editing. <em>File › Export As</em> (<kbd>Ctrl</kbd> <kbd>Shift</kbd> <kbd>E</kbd>) writes a PNG, JPEG or other file for sharing, flattened. Keep the .xcf as your working copy and export as often as you like.</p>"}],"quiz":[{"q":"Where are the settings for the active tool?","options":["The Layers panel","Tool Options","The Image menu","Preferences only"],"answer":1,"explain":"Tool Options changes with whichever tool you pick."},{"q":"Which file keeps your layers so you can edit later?","options":["PNG","JPEG","XCF","PDF"],"answer":2,"explain":"XCF is GIMP's native format; exports flatten the image."}],"exercise":{"title":"Open, look and save","task":"<p>Open <strong>lake-dull.png</strong>, zoom to 100% and then fit it to the window, find the Layers and Undo History panels, and save it as lake.xcf. How many layers does it have?</p>","files":["lake-dull.png"],"solution":["<em>File › Open</em>, choose the file.","Press <kbd>1</kbd> for 100%, then <kbd>Ctrl</kbd> <kbd>Shift</kbd> <kbd>J</kbd> to fit.","Layers panel on the right shows <strong>one layer</strong>; open Undo History with <em>Windows › Dockable Dialogs › Undo History</em> if it's not visible.","<em>File › Save As</em>, name it lake.xcf."]}},{"id":"crop","title":"Crop, straighten and resize","summary":"Straighten a crooked horizon with the Measure tool, crop to a composition or exact ratio, and resize an image for its use.","diagram":{"type":"compare","left":{"title":"Before","items":["Horizon tilted about 3°","Empty sky at the top","3000 px wide"]},"right":{"title":"After","items":["Horizon level","Cropped to 3:2","Scaled to 1600 px for the web"]},"accentRight":true,"title":"Straighten first, then crop, then resize"},"steps":[{"title":"Straighten with the Measure tool","body":"<p>Open <strong>lake-tilted.png</strong> and press <kbd>Shift</kbd> <kbd>M</kbd> for the Measure tool. Drag along the horizon from left to right. The status bar shows the angle; then select <em>Straighten</em> in Tool Options. GIMP rotates the image so your line is level.</p>"},{"title":"Crop","body":"<p>Rotating leaves transparent corners. Press <kbd>Shift</kbd> <kbd>C</kbd> for the Crop tool, tick <em>Fixed: Aspect ratio</em> in Tool Options and type <code>3:2</code>, then drag a box that avoids the corners. Drag inside the box to move it and press Enter to crop. Turn on <em>Delete cropped pixels</em> to really discard the edges.</p>"},{"title":"Canvas versus image size","body":"<p><em>Image › Scale Image</em> resizes the picture itself (making it smaller or larger); <em>Image › Canvas Size</em> changes the area around it, adding or trimming space without scaling. For the web, scale the long side to 1600 to 2000 pixels; keep the chain icon linked so the proportions stay right.</p>"},{"title":"Resolution for print","body":"<p>For print, what matters is pixels per inch at the printed size. In <em>Scale Image</em>, set the resolution to 300 pixels per inch and the width in inches to see whether the image is big enough. Scaling up adds no real detail, so start from the largest original you have.</p>"}],"quiz":[{"q":"What does Image › Canvas Size change?","options":["The picture's pixel dimensions by scaling","The area around the picture without scaling it","The resolution only","The file format"],"answer":1,"explain":"Canvas Size adds or trims space; Scale Image resizes the picture."},{"q":"Why straighten before cropping?","options":["Cropping is faster afterwards","Rotating creates empty corners that the crop can then remove","GIMP requires it","It improves colors"],"answer":1,"explain":"Crop last so the rotated corners are cut away."}],"exercise":{"title":"Level the horizon","task":"<p>Straighten <strong>lake-tilted.png</strong> with the Measure tool, crop it to 3:2 without transparent corners, scale it to 1600 pixels wide, and export it as lake-straight.jpg.</p>","files":["lake-tilted.png"],"solution":["<kbd>Shift</kbd> <kbd>M</kbd>, drag along the horizon from left to right; the status bar shows about 3°. Select <em>Straighten</em>.","<kbd>Shift</kbd> <kbd>C</kbd>, tick <em>Fixed: Aspect ratio</em>, type 3:2, drag a box inside the image clear of the corners, press Enter.","<em>Image › Scale Image</em>: width 1600 px with the chain linked, then <em>Scale</em>.","<kbd>Ctrl</kbd> <kbd>Shift</kbd> <kbd>E</kbd>, name it lake-straight.jpg, <em>Export</em>, choose a quality around 85."]}},{"id":"tone","title":"Exposure and color","summary":"Read the histogram, fix flat images with Levels, shape contrast with Curves, remove a color cast, and adjust saturation.","diagram":{"type":"levels","variant":"exposure","title":"Curves: lift or lower shadows, midtones and highlights separately"},"steps":[{"title":"The histogram","body":"<p><em>Colors › Levels</em> shows a histogram: how many pixels there are at each brightness, from black on the left to white on the right. In <strong>lake-dull.png</strong> the hump sits in the middle with empty space at both ends: no true blacks or whites, which is why it looks flat.</p>"},{"title":"Levels","body":"<p>In the Levels dialog, drag the black input slider right to where the histogram starts, and the white slider left to where it ends. Shadows get darker, highlights brighter, and the image gains contrast. The middle (gray) slider brightens or darkens midtones. Tick <em>Preview</em> to compare.</p>"},{"title":"Curves","body":"<p><em>Colors › Curves</em> gives finer control: click the line to add points and drag them. A gentle S-shape (lower point down a little, upper point up a little) adds contrast while protecting the extremes. Switch the <em>Channel</em> to Red, Green or Blue to adjust one color.</p>"},{"title":"Color cast and saturation","body":"<p>This scene has a blue cast. <em>Colors › Auto › White Balance</em> often fixes it in one step; for manual control, use <em>Colors › Color Balance</em> and move the yellow–blue slider towards yellow. <em>Colors › Hue-Saturation</em> then adds or reduces color intensity; small changes look most natural.</p>"}],"quiz":[{"q":"A histogram with empty space at both ends means…","options":["The image is too dark","It lacks true blacks and whites, so it looks flat","It's overexposed","It's black and white"],"answer":1,"explain":"Stretching the ends with Levels restores contrast."},{"q":"Which curve shape adds contrast?","options":["A straight diagonal","A gentle S-shape","A flat line","A curve raised everywhere"],"answer":1,"explain":"The S darkens shadows and brightens highlights."}],"exercise":{"title":"Bring the lake to life","task":"<p>Fix <strong>lake-dull.png</strong>: stretch the histogram with Levels, add a gentle S-curve, remove the blue cast, and raise saturation slightly. Export the result as lake-fixed.jpg and compare it with the original.</p>","files":["lake-dull.png"],"solution":["<em>Colors › Levels</em>: drag the black input slider to the left edge of the histogram hump and the white slider to its right edge; <em>OK</em>.","<em>Colors › Curves</em>: add a point at about a quarter up and pull it slightly down, another at three quarters and pull it slightly up.","<em>Colors › Auto › White Balance</em> removes the blue tint (or <em>Color Balance</em>, midtones, a little towards yellow).","<em>Colors › Hue-Saturation</em>: Saturation +10 to +20.","<kbd>Ctrl</kbd> <kbd>Shift</kbd> <kbd>E</kbd> to export lake-fixed.jpg. The sky is bluer, the trees greener and the water darker."]}},{"id":"retouch","title":"Retouching: healing and cloning","summary":"Remove dust and blemishes with the Heal tool, copy texture with the Clone tool, and work non-destructively on a separate layer.","diagram":{"type":"flow","nodes":["New empty layer","Ctrl+click a clean source","Paint over the spot","Check at 100%"],"highlight":1,"title":"Heal and Clone both copy from a source you choose"},"steps":[{"title":"Work on a separate layer","body":"<p>Open <strong>old-scan.png</strong>. Press <kbd>Ctrl</kbd> <kbd>Shift</kbd> <kbd>N</kbd> to add a transparent layer named “Retouch”. In the Heal or Clone tool's options, tick <em>Sample merged</em> so they copy from what you see, while painting only on the new layer. If you overdo it, erase part of the layer; the original is untouched.</p>"},{"title":"The Heal tool","body":"<p>Press <kbd>H</kbd>. Hold <kbd>Ctrl</kbd> and click a clean area near the spot to set the source, then paint over the dust. Heal blends the copied texture with the surroundings' color and brightness, so it's ideal for specks on smooth areas such as sky. Size the brush with <kbd>[</kbd> and <kbd>]</kbd>, just larger than the speck.</p>"},{"title":"The Clone tool","body":"<p>Press <kbd>C</kbd>. It works the same way but copies pixels exactly, without blending. Use it for edges and patterns, such as where the scratch crosses the edge of the sun, where you need to continue the sun's curved edge rather than smooth it over. Re-sample often so repeated patterns don't give you away.</p>"},{"title":"Check your work","body":"<p>Press <kbd>1</kbd> to view at 100% and pan across the image. Toggle the Retouch layer's eye icon to compare before and after. Small, varied strokes look more natural than long sweeps.</p>"}],"quiz":[{"q":"What's the main difference between Heal and Clone?","options":["Heal is faster","Heal blends with the surrounding color and brightness; Clone copies pixels exactly","Clone only works on text","Heal needs a selection"],"answer":1,"explain":"Use Heal on smooth areas and Clone where structure must continue."},{"q":"Why retouch on a new layer with Sample merged ticked?","options":["It's required","The original stays untouched and mistakes are easy to undo","It makes the file smaller","It sharpens the image"],"answer":1,"explain":"Non-destructive edits can be adjusted later."}],"exercise":{"title":"Clean up the scan","task":"<p>On a separate layer, remove the dust specks from the sky of <strong>old-scan.png</strong> with the Heal tool and repair the scratch with the Clone tool. Compare before and after by toggling the layer, then export old-scan-clean.png.</p>","files":["old-scan.png"],"solution":["<kbd>Ctrl</kbd> <kbd>Shift</kbd> <kbd>N</kbd>, name the layer Retouch, fill type Transparency.","<kbd>H</kbd>, tick <em>Sample merged</em>, size the brush to just cover a speck, Ctrl+click clean sky nearby, then click each speck.","Heal the scratch across the sky the same way. Where it crosses the sun, switch to <kbd>C</kbd>: Ctrl+click an unscratched part of the sun's edge and paint along it in short strokes.","Click the Retouch layer's eye icon on and off to compare.","<kbd>Ctrl</kbd> <kbd>Shift</kbd> <kbd>E</kbd>, export old-scan-clean.png."]}},{"id":"selections","title":"Selections, masks and cutouts","summary":"Select a subject with the right tool, refine the edge, cut it out with a layer mask, and place it on a new background.","diagram":{"type":"layers","items":["Mug layer with a layer mask","New background layer (gradient)"],"highlight":0,"caption":"White in a mask shows the layer; black hides it"},"steps":[{"title":"Pick a selection tool","body":"<p>Open <strong>mug-product.png</strong>. The background is a smooth gray, so the easiest route is to select the background and invert: press <kbd>U</kbd> for Fuzzy Select, click the gray (adjust <em>Threshold</em> in Tool Options if it misses parts), then hold <kbd>Shift</kbd> and click the gray inside the handle too, because it isn't connected to the rest. Press <kbd>Ctrl</kbd> <kbd>I</kbd> to invert so the mug is selected.</p>"},{"title":"Refine the edge","body":"<p>Hold <kbd>Shift</kbd> while using a selection tool to add to the selection, <kbd>Ctrl</kbd> to subtract. <em>Select › Shrink</em> by 1 pixel removes a gray fringe; <em>Select › Feather</em> by 1 to 2 pixels softens the edge so it blends naturally. Press Shift+Q to see the selection as a red overlay (Quick Mask) and check it.</p>"},{"title":"Layer masks","body":"<p>Instead of deleting the background, hide it. Right-click the layer and choose <em>Add Layer Mask</em>, pick <em>Selection</em> and select <em>Add</em>. White areas of the mask show the layer; black areas hide it. To fix the edge later, paint on the mask with black or white.</p>"},{"title":"A new background","body":"<p>Press <kbd>Ctrl</kbd> <kbd>Shift</kbd> <kbd>N</kbd> for a new layer, drag it below the mug in the Layers panel, and fill it with the Gradient tool (<kbd>G</kbd>) or a color. The mug now sits on the new background. Export as PNG to keep transparency, or as JPEG once a background is in place.</p>"}],"quiz":[{"q":"Why select the background and invert, instead of selecting the mug directly?","options":["Inverting is required","A plain background is easier to select accurately in one click","The mug can't be selected","It's faster to export"],"answer":1,"explain":"Fuzzy Select works best on smooth, even areas."},{"q":"On a layer mask, what does black do?","options":["Shows the layer","Hides the layer","Darkens the layer","Deletes the layer"],"answer":1,"explain":"White reveals, black conceals, gray is partly transparent."}],"exercise":{"title":"Cut out the mug","task":"<p>Select the mug in <strong>mug-product.png</strong>, refine the edge, hide the gray background with a layer mask, place a soft gradient behind it, and export two versions: mug-transparent.png (no background) and mug-final.jpg.</p>","files":["mug-product.png"],"solution":["<kbd>U</kbd>, click the gray background, Shift+click the gray inside the handle (and the shadow, unless you want to keep it), then <kbd>Ctrl</kbd> <kbd>I</kbd> to invert.","<em>Select › Shrink</em> 1 px, then <em>Select › Feather</em> 1.5 px.","Layers panel: right-click the layer › <em>Add Layer Mask</em> › <em>Selection</em> › <em>Add</em>. If the layer has no alpha channel, GIMP adds one automatically.","Export mug-transparent.png now. Then add a new layer, move it below, and drag a gradient across it.","Export mug-final.jpg."]}},{"id":"finish","title":"Text, sharpening and export","summary":"Add text, sharpen for the final size, export the right format at the right quality, and batch-friendly habits.","diagram":{"type":"table","head":["Use","Format","Notes"],"rows":[["Photos on the web","JPEG or WebP","Quality 80–85, long side 1600–2000 px"],["Graphics, transparency","PNG","Lossless, larger files"],["Print","TIFF or high-quality JPEG","300 ppi at print size"]],"highlight":{"rows":[0]},"caption":"Choose the export format for where the image is going"},"steps":[{"title":"Add text","body":"<p>Press <kbd>T</kbd>, click on the image and type. Change the font, size and color in Tool Options or the floating text toolbar. Each text box is its own layer; move it with the Move tool (<kbd>M</kbd>). For readability on a photo, add a semi-transparent dark layer behind the text.</p>"},{"title":"Sharpen last","body":"<p>Sharpen after resizing, for the final size. <em>Filters › Enhance › Sharpen (Unsharp Mask)</em>: a small Radius (about 1) and modest Amount (0.3 to 0.6) at 100% zoom. Too much shows as bright halos along edges.</p>"},{"title":"Export options","body":"<p><em>File › Export As</em> picks the format from the extension you type. JPEG quality 80 to 85 is a good balance for photos. Under <em>Advanced options</em>, you can strip metadata such as the camera's location data before sharing. PNG keeps transparency; WebP makes smaller files for the web.</p>"},{"title":"Good habits","body":"<p>Keep originals untouched, work in an .xcf, and name exports by their use (lake-web.jpg, lake-print.tif). <em>File › Overwrite</em> updates the last exported file in one step after small changes.</p>"}],"quiz":[{"q":"When should you sharpen?","options":["First, before anything else","Last, after resizing to the final size","Before cropping","Never"],"answer":1,"explain":"Sharpening depends on the final pixel size."},{"q":"Which format keeps transparency?","options":["JPEG","PNG","BMP","All of them"],"answer":1,"explain":"PNG (and WebP) support transparency; JPEG doesn't."}],"exercise":{"title":"A captioned web image","task":"<p>Take your fixed lake photo, add the caption “Lake Ardel, early autumn” on a soft dark band along the bottom, sharpen lightly, and export a 1600-pixel JPEG at quality 85 with metadata stripped.</p>","files":["lake-dull.png"],"solution":["Open your lake.xcf (or lake-fixed.jpg). Scale to 1600 px wide if needed.","New layer; Rectangle Select a band along the bottom, fill it black, set the layer's opacity to about 40%.","<kbd>T</kbd>, click on the band, type the caption in white.","Select the photo layer, <em>Filters › Enhance › Sharpen (Unsharp Mask)</em>: Radius 1, Amount 0.4.","<kbd>Ctrl</kbd> <kbd>Shift</kbd> <kbd>E</kbd>, lake-web.jpg, Quality 85, untick the metadata options under Advanced options, <em>Export</em>."]}}],"extras":{"project":{"id":"bonus-collage","title":"Bonus project: a three-photo collage","summary":"Build a square collage from three images with guides, layer masks and consistent color, ready for social media.","diagram":{"type":"frames","variant":"nest","title":"A grid of frames: one large, two small"},"steps":[{"title":"Canvas and guides","body":"<p><em>File › New</em>: 1080 × 1080 pixels. <em>Image › Guides › New Guide (by Percent)</em> adds guides at 50% vertical and 50% horizontal on the right half. The left half holds one large image, the right two smaller ones.</p>"},{"title":"Place images with masks","body":"<p><em>File › Open as Layers</em> brings each image in as a layer. Scale each with <kbd>Shift</kbd> <kbd>S</kbd> so it covers its cell, then Rectangle Select the cell (it snaps to the guides) and add a layer mask from the selection. The masks crop without throwing away pixels, so you can reposition later.</p>"},{"title":"Make it consistent","body":"<p>Different photos rarely match. Apply similar Curves to each, or add a single color layer on top in <em>Soft light</em> mode at low opacity to tie them together. Leave a thin, even gap between cells for a clean look.</p>"}],"quiz":[{"q":"Why crop each image with a layer mask instead of the Crop tool?","options":["Masks are faster","You can reposition the image later because no pixels are deleted","The Crop tool can't crop layers","Masks improve color"],"answer":1,"explain":"Masks hide rather than delete."},{"q":"What does File › Open as Layers do?","options":["Opens a new window","Adds the chosen images as layers in the current image","Merges all layers","Exports layers"],"answer":1,"explain":"It's the quick way to combine images."}],"exercise":{"title":"Make the collage","task":"<p>Combine your fixed lake photo, the cleaned scan and the mug cutout into a 1080 × 1080 collage with even gaps, one shared color treatment, and export it as collage.jpg.</p>","files":["lake-dull.png","old-scan.png","mug-product.png"],"solution":["<em>File › New</em> 1080 × 1080; add guides at 50% vertical and, for the right half, 50% horizontal.","<em>File › Open as Layers</em> for the three images.","For each: <kbd>Shift</kbd> <kbd>S</kbd> to scale it over its cell, <kbd>R</kbd> to select the cell (shrink it 6 px for the gap with <em>Select › Shrink</em>), then <em>Add Layer Mask › Selection</em>.","Add a top layer filled with a warm color, mode <em>Soft light</em>, opacity 20%.","<kbd>Ctrl</kbd> <kbd>Shift</kbd> <kbd>E</kbd> as collage.jpg."]}},"quizbank":[{"q":"Which key selects the Fuzzy Select tool?","options":["F","U","S","W"],"answer":1,"explain":"U is Fuzzy Select; F is Free Select."},{"q":"What does pressing 1 do in GIMP?","options":["Opens the first image","Zooms to 100%","Selects layer 1","Sets opacity to 100%"],"answer":1,"explain":"1 shows the image at actual pixels."},{"q":"Which menu holds Levels and Curves?","options":["Image","Colors","Filters","Layer"],"answer":1,"explain":"Tonal and color adjustments are under Colors."},{"q":"How do you set the source for the Heal or Clone tool?","options":["Right-click","Ctrl+click the source area","Shift+click","Double-click"],"answer":1,"explain":"Ctrl+click sets where pixels are copied from."},{"q":"What does Select › Feather do?","options":["Removes the selection","Softens the selection's edge","Grows the selection","Inverts it"],"answer":1,"explain":"Feathering blends the edge over a few pixels."},{"q":"You export a cutout as JPEG and the background turns white. Why?","options":["A bug","JPEG doesn't support transparency","The mask was deleted","Feathering was too high"],"answer":1,"explain":"Use PNG or WebP to keep transparency."},{"q":"What does Image › Scale Image change?","options":["Only the canvas","The image's pixel dimensions","The file format","The color mode"],"answer":1,"explain":"Scale Image resizes the picture itself."},{"q":"Which shortcut adds a new layer?","options":["Ctrl+N","Ctrl+Shift+N","Ctrl+L","Shift+N"],"answer":1,"explain":"Ctrl+N is a new image; Ctrl+Shift+N a new layer."}]},"versionNote":"Software makers update their programs, so menus and button locations can change between versions. This guide is revised when an update changes the steps, and the revised version appears the next time you open it."};
